// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra;

import static org.assertj.core.api.Assertions.assertThat;

import org.junit.jupiter.api.Test;

/**
 * Binding-name order is part of what planners number symbols by. A FILTER EXISTS declares its argument's names and then
 * its sub-query's names in that order, independently of how the names hash.
 */
class FilterBindingNamesTest {

	private static StatementPattern pattern(String subject, String object) {
		return new StatementPattern(new Var(subject), new Var("link"), new Var(object));
	}

	@Test
	void existsFilterDeclaresArgumentNamesFirstThenSubQueryNamesInOrder() {
		// A hash set iterates these names as subject, tail, link, inner, object.
		Filter filter = new Filter(pattern("subject", "object"),
				new Exists(new Join(pattern("object", "inner"), pattern("inner", "tail"))));

		assertThat(filter.getBindingNames()).containsExactly("subject", "link", "object", "inner", "tail");
		assertThat(filter.getAssuredBindingNames()).containsExactly("subject", "link", "object");
	}

	@Test
	void ordinaryFilterKeepsItsArgumentNames() {
		StatementPattern argument = pattern("subject", "object");
		Filter filter = new Filter(argument, new Not(new Exists(pattern("object", "inner"))));

		assertThat(filter.getBindingNames()).containsExactly("subject", "link", "object");
	}
}
